"""Stand-in print hosts for the printer chat's connection test.

Each HTTP port plays one connection type, answering the requests that type's
test sends the way that host documents, and refusing a missing key where the
host does. Fixed-port TCP types (MKS 8080, Flashforge 8899) answer "ok" to a
G-code line. Every connection and request is logged to the file named first.

Usage: standin.py <log> [--flashforge-legacy] [--no-mks]
  --flashforge-legacy  also listen on 8899, like an older Flashforge
                       (without it 8899 stays closed, as the issue reports for
                       the Creator 5 Pro, and 8898 answers the HTTP API)
"""
import json
import socket
import sys
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

KEY = "standin-key-1"  # the stand-ins' test key, made up here
LOG = open(sys.argv[1], "a", buffering=1)
lock = threading.Lock()


def log(line):
    with lock:
        LOG.write(line + "\n")


def handler_for(kind):
    class H(BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def reply(self, status, body, ctype="application/json"):
            data = body.encode() if isinstance(body, str) else body
            self.send_response(status)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            log(f"{kind}:{self.server.server_port} <- {status} {data[:80]!r}")

        def handle_any(self, method):
            url = urlsplit(self.path)
            q = parse_qs(url.query)
            n = int(self.headers.get("Content-Length") or 0)
            body = self.rfile.read(n).decode(errors="replace") if n else ""
            heard = {h: self.headers[h] for h in ("X-Api-Key", "X-Token", "serialNumber", "checkCode") if self.headers.get(h)}
            if self.headers.get("Authorization"):
                heard["Authorization"] = self.headers["Authorization"].split(" ")[0]
            log(f"{kind}:{self.server.server_port} -> {method} {self.path} headers={heard} body={body[:200]!r}")
            key = self.headers.get("X-Api-Key") or (q.get("apikey") or [None])[0]
            p = url.path
            if kind == "moonraker" and p == "/server/info":
                if key != KEY:
                    return self.reply(401, json.dumps({"error": {"code": 401, "message": "Unauthorized"}}))
                return self.reply(200, json.dumps({"result": {"klippy_state": "ready", "moonraker_version": "v0.9.3"}}))
            if kind in ("octoprint", "prusalink", "astrobox") and p == "/api/version":
                if kind == "octoprint" and key is None:
                    return self.reply(403, json.dumps({"error": "You don't have the permission to access the requested resource."}))
                if kind == "octoprint" and key != KEY:
                    return self.reply(403, json.dumps({"error": "Invalid API key"}))
                if kind == "prusalink" and key != KEY:
                    return self.reply(401, json.dumps({"error": "Unauthorized"}))
                text = {"octoprint": "OctoPrint 1.9.3", "prusalink": "PrusaLink 0.8.1", "astrobox": "AstroBox 1.6.0"}[kind]
                return self.reply(200, json.dumps({"api": "0.1", "server": "1.9.3", "text": text}))
            if kind == "duet" and p == "/rr_connect":
                return self.reply(200, json.dumps({"err": 0, "sessionTimeout": 8000, "boardType": "duetwifi102"}))
            if kind == "ultimaker" and p == "/api/v1/system/variant":
                return self.reply(200, '"Ultimaker S5"')
            if kind == "ultimaker" and p.startswith("/api/v1/auth"):
                return self.reply(200, json.dumps({"message": "unauthorized"}))
            if kind == "flashair" and p == "/command.cgi":
                return self.reply(200, "1", "text/plain")
            if kind == "repetier" and p == "/printer/info":
                if key != KEY:
                    return self.reply(401, json.dumps({"error": "Missing or wrong api key"}))
                return self.reply(200, json.dumps({"name": "Repetier-Server", "software": "Repetier-Server",
                                                   "version": "1.4.13", "printers": [{"slug": "ender3", "name": "Ender 3"}]}))
            if kind == "esp3d" and p == "/command":
                return self.reply(200, "ok T:21.0 /0.0 B:20.5 /0.0", "text/plain")
            if kind == "crealityprint" and p == "/info":
                return self.reply(200, json.dumps({"model": "K1C", "version": "1.3.3.5"}))
            if kind == "elegoo_cc" and p == "/":
                return self.reply(200, "<html><title>ELEGOO</title></html>", "text/html")
            if kind == "elegoo_cc2" and p == "/system/info":
                if self.headers.get("X-Token") not in (KEY, "123456"):
                    return self.reply(401, json.dumps({"error_code": 401, "message": "Unauthorized"}))
                return self.reply(200, json.dumps({"error_code": 0, "system_info": {"sn": "CC2STANDIN01", "model": "Centauri Carbon 2"}}))
            if kind == "flashforge_http" and p == "/detail":
                try:
                    req = json.loads(body)
                except ValueError:
                    req = {}
                if req.get("checkCode") != KEY:
                    return self.reply(200, json.dumps({"code": 1, "message": "check code error"}))
                return self.reply(200, json.dumps({"code": 0, "message": "Success", "detail": {"status": "ready", "name": "Creator 5 Pro"}}))
            return self.reply(404, json.dumps({"error": "not found"}))

        def do_GET(self):
            self.handle_any("GET")

        def do_POST(self):
            self.handle_any("POST")

    return H


def tcp_ok(port, kind):
    srv = socket.socket()
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind(("127.0.0.1", port))
    srv.listen()

    def serve():
        while True:
            conn, _ = srv.accept()
            log(f"{kind}:{port} -> TCP connection")
            conn.settimeout(5)
            try:
                data = conn.recv(1024)
                log(f"{kind}:{port} -> {data!r}")
                answer = b"CMD M601 Received.\r\nControl Success.\r\nok\r\n" if kind == "flashforge_tcp" else b"ok\n"
                conn.sendall(answer)
                log(f"{kind}:{port} <- {answer!r}")
            except OSError as e:
                log(f"{kind}:{port} !! {e}")
            finally:
                conn.close()

    threading.Thread(target=serve, daemon=True).start()


HTTP = {18001: "moonraker", 18002: "octoprint", 18003: "prusalink", 18004: "duet", 18005: "ultimaker",
        18006: "flashair", 18007: "astrobox", 18008: "repetier", 18009: "esp3d", 18010: "crealityprint",
        18011: "elegoo_cc", 18012: "elegoo_cc2", 8898: "flashforge_http"}

for port, kind in HTTP.items():
    s = ThreadingHTTPServer(("127.0.0.1", port), handler_for(kind))
    threading.Thread(target=s.serve_forever, daemon=True).start()
if "--no-mks" not in sys.argv:
    tcp_ok(8080, "mks")
if "--flashforge-legacy" in sys.argv:
    tcp_ok(8899, "flashforge_tcp")
log("READY " + " ".join(sys.argv[2:]))
threading.Event().wait()

